fields.InputDefinition:
{
  "goal": "Do the shared setup ONCE: open the 'Event Registrations' entity via the LEFT sidebar 'Search entities...' box (type 'Event Registrations', click the exact match), click any row, then click 'Open Full Record', then click the Edit (pencil) button to enter edit mode. A foreign-key field (e.g. 'Member' or 'Event') renders as a text box with a magnifying-glass icon. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) fk-typeahead-search — click the FK field and type a few characters; a dropdown of matching related records should appear (or a clear 'No matches' state); (2) fk-create-new-footer — type a value unlikely to match anything (e.g. 'ZZQX Nonexistent') and look at the bottom of the FK search dropdown for a sticky 'Create new...' footer button prefilled with the typed text (or, if the user lacks create permission, the footer being deliberately absent while a no-match state still shows); (3) fk-scope-column-picker — click/focus the FK field and look for a small scope 'pill' (magnifying-glass + field name + chevron); click it to open a field-scope/column-visibility menu, OR confirm the results dropdown renders sortable column headers. You do NOT need to save anything. Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "fk-typeahead-search",
      "instruction": "FK field typeahead shows matching suggestions",
      "visualCriteria": [
        "In edit mode, a foreign-key field renders as a searchable text input with a magnifying-glass icon (not a plain dropdown), and typing into it triggers a dropdown of matching related-record suggestions OR a clear 'No matches' empty state"
      ]
    },
    {
      "name": "fk-create-new-footer",
      "instruction": "Create-new footer in FK search dropdown",
      "visualCriteria": [
        "Typing a non-matching value in the foreign-key field renders the FK search dropdown with a 'Create new...' footer button (plus icon) prefilled with the typed text, OR the footer is deliberately absent (user lacks create permission) while the dropdown still shows a no-match state"
      ]
    },
    {
      "name": "fk-scope-column-picker",
      "instruction": "FK scope pill / column picker or sortable result headers",
      "visualCriteria": [
        "Focusing the FK field shows the search UI with either a scope pill that opens a field-scope/column-visibility menu when clicked, OR a results dropdown that clearly renders sortable column headers"
      ]
    }
  ]
}
